use std::char;

pub fn shift(text: &str, amount: i32) -> String {
    text.chars()
        .map(|character| {
            if character.is_ascii_lowercase() {
                let offset = (character as u8 - b'a').wrapping_add(amount as u8) % 26;
                (b'a' + offset) as char
            } else if character.is_ascii_uppercase() {
                let offset = (character as u8 - b'A').wrapping_add(amount as u8) % 26;
                (b'A' + offset) as char
            } else {
                character
            }
        })
        .collect()
}
